async function migrateUsersToHashedPasswords(){if(!AppState.appData.users||!Array.isArray(AppState.appData.users))return;const s=AppState.appData.users.filter(a=>a.passwordHash?!1:a.password&&typeof a.password=="string");if(s.length!==0){Utils.safeLog(`\u{1F504} \u0628\u062F\u0621 \u062A\u062D\u0648\u064A\u0644 ${s.length} \u0645\u0633\u062A\u062E\u062F\u0645 \u0625\u0644\u0649 passwordHash...`);for(const a of s)try{a.passwordHash=await Utils.hashPassword(a.password),delete a.password,Utils.safeLog(`\u2705 \u062A\u0645 \u062A\u062D\u0648\u064A\u0644 \u0643\u0644\u0645\u0629 \u0627\u0644\u0645\u0631\u0648\u0631 \u0644\u0644\u0645\u0633\u062A\u062E\u062F\u0645: ${a.email}`)}catch(e){Utils.safeError(`\u274C \u0641\u0634\u0644 \u062A\u062D\u0648\u064A\u0644 \u0643\u0644\u0645\u0629 \u0627\u0644\u0645\u0631\u0648\u0631 \u0644\u0644\u0645\u0633\u062A\u062E\u062F\u0645 ${a.email}:`,e)}typeof window.DataManager<"u"&&window.DataManager.save?window.DataManager.save():Utils.safeWarn("\u26A0\uFE0F DataManager \u063A\u064A\u0631 \u0645\u062A\u0627\u062D - \u0644\u0645 \u064A\u062A\u0645 \u062D\u0641\u0638 \u0627\u0644\u062A\u063A\u064A\u064A\u0631\u0627\u062A"),Utils.safeLog(`\u2705 \u062A\u0645 \u062A\u062D\u0648\u064A\u0644 ${s.length} \u0645\u0633\u062A\u062E\u062F\u0645 \u0628\u0646\u062C\u0627\u062D`)}}typeof window<"u"&&(window.migrateUsersToHashedPasswords=migrateUsersToHashedPasswords);
